<?php
function sk1180_render_crm_page(array $b,array $u,bool $admin=false): void {$bid=(int)$b['id'];$uid=(int)$u['id'];$name=(string)sk1130_business_value($b,['name'],'Business');$stats=sk1180_crm_stats($bid);$contacts=sk1180_contacts($bid,200);$convs=sk1180_conversations($bid,150);$quotes=sk1180_quotes($bid,0,100);$follow=sk1180_followups($bid,100);$activeConv=(int)($_GET['conversation_id']??0);$activeContact=(int)($_GET['contact_id']??0);$convRow=[];$msgs=[];if($activeConv){foreach($convs as $x)if((int)$x['id']===$activeConv){$convRow=$x;break;}$msgs=sk1180_messages($activeConv,200);$activeContact=(int)($convRow['contact_id']??$activeContact);}?>
<link rel="stylesheet" href="/assets/business-crm-v1180.css?v=1180"><div class="crm1180"><section class="hero"><div><span>SHAHKOTPK v11.8</span><h1><?=sk1130_h($name)?> Customer CRM</h1><p>Manage customer conversations, quotations and follow-ups from one business workspace.</p></div><div><a href="/business-site.php?id=<?=$bid?>" target="_blank">Website ↗</a><a href="/business-contact-v1180.php?business_id=<?=$bid?>" target="_blank">Customer Chat ↗</a></div></section><div class="metrics"><article><b><?=$stats['contacts']?></b><span>contacts</span></article><article><b><?=$stats['open_chats']?></b><span>open chats</span></article><article><b><?=$stats['quotes']?></b><span>active quotes</span></article><article><b>PKR <?=number_format($stats['quote_value'],0)?></b><span>quote value</span></article><article><b><?=$stats['followups']?></b><span>follow-ups</span></article></div><nav class="tabs"><a href="?business_id=<?=$bid?>#conversations">Conversations</a><a href="?business_id=<?=$bid?>#contacts">Customers</a><a href="?business_id=<?=$bid?>#quotes">Quotes</a><a href="?business_id=<?=$bid?>#followups">Follow-ups</a></nav>
<section class="panel" id="conversations"><div class="panel-head"><div><span>INBOX</span><h2>Customer conversations</h2></div></div><div class="split"><div class="list"><?php foreach($convs as $x):?><a class="list-row <?=$activeConv===(int)$x['id']?'active':''?>" href="?business_id=<?=$bid?>&conversation_id=<?=(int)$x['id']?>#conversation"><b><?=sk1130_h($x['customer_name']?:'Customer')?></b><span><?=sk1130_h($x['subject'])?></span><small><?=sk1130_h(mb_substr((string)$x['last_message'],0,90))?></small></a><?php endforeach;?><?php if(!$convs):?><p class="empty">No customer conversations yet.</p><?php endif;?></div><div class="conversation" id="conversation"><?php if($convRow):?><header><h3><?=sk1130_h($convRow['customer_name']?:'Customer')?></h3><span><?=sk1130_h($convRow['phone'])?> <?=sk1130_h($convRow['email'])?></span></header><div class="messages"><?php foreach($msgs as $m):?><article class="msg <?=sk1130_h($m['sender_type'])?>"><small><?=sk1130_h($m['sender_type'])?> · <?=sk1130_h($m['created_at'])?></small><p><?=nl2br(sk1130_h($m['message']))?></p></article><?php endforeach;?></div><form method="post" class="reply"><input type="hidden" name="_csrf" value="<?=sk1130_h(csrf_token())?>"><input type="hidden" name="business_id" value="<?=$bid?>"><input type="hidden" name="action" value="reply"><input type="hidden" name="conversation_id" value="<?=$activeConv?>"><textarea required name="message" rows="3" placeholder="Reply to customer…"></textarea><button>Send reply</button></form><?php else:?><div class="empty">Choose a conversation to reply.</div><?php endif;?></div></div></section>
<section class="panel" id="contacts"><div class="panel-head"><div><span>CRM</span><h2>Customers & leads</h2></div></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Contact</th><th>Status</th><th>Chats</th><th>Quotes</th><th>Last activity</th><th></th></tr></thead><tbody><?php foreach($contacts as $c):?><tr><td><b><?=sk1130_h($c['customer_name'])?></b></td><td><?=sk1130_h($c['phone'])?><br><small><?=sk1130_h($c['email'])?></small></td><td><?=sk1130_h($c['status'])?></td><td><?=(int)$c['conversations']?></td><td><?=(int)$c['quotes']?></td><td><?=sk1130_h($c['last_contact_at'])?></td><td><a href="?business_id=<?=$bid?>&contact_id=<?=(int)$c['id']?>#quote-new">Quote</a></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel" id="quote-new"><div class="panel-head"><div><span>QUOTATION</span><h2>Create customer quote</h2></div></div><form method="post" class="quote-form"><input type="hidden" name="_csrf" value="<?=sk1130_h(csrf_token())?>"><input type="hidden" name="business_id" value="<?=$bid?>"><input type="hidden" name="action" value="quote"><label>Customer<select name="contact_id" required><option value="">Select customer</option><?php foreach($contacts as $c):?><option value="<?=(int)$c['id']?>" <?=$activeContact===(int)$c['id']?'selected':''?>><?=sk1130_h($c['customer_name'])?> — <?=sk1130_h($c['phone']?:$c['email'])?></option><?php endforeach;?></select></label><input type="hidden" name="conversation_id" value="<?=$activeConv?>"><div class="grid"><label>Quote title<input name="title" value="Quotation"></label><label>Valid until<input type="date" name="valid_until"></label><label>Discount (PKR)<input type="number" step="0.01" min="0" name="discount_amount" value="0"></label></div><div class="quote-items"><div><input name="items[0][name]" placeholder="Service / product" required><input name="items[0][description]" placeholder="Description"><input type="number" step="0.01" min="0.01" name="items[0][qty]" value="1"><input type="number" step="0.01" min="0" name="items[0][price]" placeholder="Unit price"></div><div><input name="items[1][name]" placeholder="Optional item"><input name="items[1][description]" placeholder="Description"><input type="number" step="0.01" min="0.01" name="items[1][qty]" value="1"><input type="number" step="0.01" min="0" name="items[1][price]" placeholder="Unit price"></div><div><input name="items[2][name]" placeholder="Optional item"><input name="items[2][description]" placeholder="Description"><input type="number" step="0.01" min="0.01" name="items[2][qty]" value="1"><input type="number" step="0.01" min="0" name="items[2][price]" placeholder="Unit price"></div></div><label>Note<textarea name="note" rows="3" placeholder="Terms, delivery time or other factual details…"></textarea></label><button>Create & Send Quote</button></form></section>
<section class="panel" id="quotes"><div class="panel-head"><div><span>PIPELINE</span><h2>Quotations</h2></div></div><div class="cards"><?php foreach($quotes as $q):?><article><div><b><?=sk1130_h($q['quote_no'])?></b><span><?=sk1130_h($q['status'])?></span></div><h3><?=sk1130_h($q['customer_name']?:'Customer')?></h3><p><?=sk1130_h($q['title'])?></p><strong>PKR <?=number_format((float)$q['total_amount'],0)?></strong><?php if($q['valid_until']):?><small>Valid until <?=sk1130_h($q['valid_until'])?></small><?php endif;?></article><?php endforeach;?></div></section>
<section class="panel" id="followups"><div class="panel-head"><div><span>FOLLOW-UP</span><h2>Tasks & reminders</h2></div></div><form method="post" class="follow-form"><input type="hidden" name="_csrf" value="<?=sk1130_h(csrf_token())?>"><input type="hidden" name="business_id" value="<?=$bid?>"><input type="hidden" name="action" value="followup"><select required name="contact_id"><option value="">Customer</option><?php foreach($contacts as $c):?><option value="<?=(int)$c['id']?>"><?=sk1130_h($c['customer_name'])?></option><?php endforeach;?></select><input required type="datetime-local" name="due_at"><input name="note" required placeholder="Follow up about quotation / booking / service…"><button>Add follow-up</button></form><div class="follow-list"><?php foreach($follow as $f):?><article class="<?=$f['status']==='done'?'done':''?>"><div><b><?=sk1130_h($f['customer_name'])?></b><span><?=sk1130_h($f['due_at'])?></span><p><?=sk1130_h($f['note'])?></p></div><?php if($f['status']!=='done'):?><form method="post"><input type="hidden" name="_csrf" value="<?=sk1130_h(csrf_token())?>"><input type="hidden" name="business_id" value="<?=$bid?>"><input type="hidden" name="action" value="followup_done"><input type="hidden" name="followup_id" value="<?=(int)$f['id']?>"><button>Done</button></form><?php endif;?></article><?php endforeach;?></div></section></div><?php }
